import test from 'node:test';
import assert from 'node:assert/strict';
import { statement } from '../src/statements.js';
import { createInvoice, issueInvoice } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('statement returns invoices for a customer', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const r2 = issueInvoice(r1.value, []);
  const invoices = [r2.value];

  const result = statement('C-001', invoices, '2026-10-31');
  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.invoices.length, 1);
  assert.equal(result.value.invoices[0].number, 'INV-2026-0001');
  assert.equal(result.value.invoices[0].issueDate, '2026-10-01');
});

test('statement filters by customer ID', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const r2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-02',
    lines: [{ sku: 'DEV-HOUR', qty: 3 }],
  });

  const i1 = issueInvoice(r1.value, []);
  const i2 = issueInvoice(r2.value, ['INV-2026-0001']);
  const invoices = [i1.value, i2.value];

  const result = statement('C-001', invoices, '2026-10-31');
  assert.equal(result.value.invoices.length, 1);
  assert.equal(result.value.invoices[0].number, 'INV-2026-0001');
});

test('statement normalizes customer ID', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const r2 = issueInvoice(r1.value, []);
  const invoices = [r2.value];

  const result = statement('c-001 ', invoices, '2026-10-31');
  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
});

test('statement filters by status', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const invoices = [r1.value];

  const result = statement('C-001', invoices, '2026-10-31');
  assert.equal(result.value.invoices.length, 0);
});

test('statement includes issued and partially_paid invoices', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const r2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-05',
    lines: [{ sku: 'DEV-HOUR', qty: 3 }],
  });

  const i1 = issueInvoice(r1.value, []);
  const i2 = issueInvoice(r2.value, ['INV-2026-0001']);

  const p2 = recordPayment(i2.value, { amount: 10000, date: '2026-10-10' });

  const invoices = [i1.value, p2.value];

  const result = statement('C-001', invoices, '2026-10-31');
  assert.equal(result.value.invoices.length, 2);
});

test('statement filters by date', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const r2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 3 }],
  });

  const i1 = issueInvoice(r1.value, []);
  const i2 = issueInvoice(r2.value, ['INV-2026-0001']);

  const invoices = [i1.value, i2.value];

  const result1 = statement('C-001', invoices, '2026-10-10');
  assert.equal(result1.value.invoices.length, 1);
  assert.equal(result1.value.invoices[0].issueDate, '2026-10-01');

  const result2 = statement('C-001', invoices, '2026-10-31');
  assert.equal(result2.value.invoices.length, 2);
});

test('statement sorts by issueDate', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const r2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-05',
    lines: [{ sku: 'DEV-HOUR', qty: 3 }],
  });

  const i1 = issueInvoice(r1.value, []);
  const i2 = issueInvoice(r2.value, ['INV-2026-0001']);

  const invoices = [i1.value, i2.value];

  const result = statement('C-001', invoices, '2026-10-31');
  assert.equal(result.value.invoices[0].issueDate, '2026-10-05');
  assert.equal(result.value.invoices[1].issueDate, '2026-10-15');
});

