  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'STICKER', qty: 100, discountPercent: 0 }],
  });

  const r2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-05',
    lines: [{ sku: 'STICKER', qty: 50, discountPercent: 0 }],
  });

  const i1 = issueInvoice(r1.value, []);
  const i2 = issueInvoice(r2.value, ['INV-2026-0001']);

  const invoices = [i1.value, i2.value];

  const result = statement('C-001', invoices, '2026-10-31');
  const sum = result.value.invoices.reduce((acc, inv) => acc + inv.due, 0);
  assert.equal(result.value.totalDue, sum);
});

test('statement totalDue excludes paid invoices', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'STICKER', qty: 100, discountPercent: 0 }],
  });

  const r2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-05',
    lines: [{ sku: 'STICKER', qty: 50, discountPercent: 0 }],
  });

  const i1 = issueInvoice(r1.value, []);
  const i2 = issueInvoice(r2.value, ['INV-2026-0001']);

  const p1Totals = invoiceTotals(i1.value);
  const p2 = recordPayment(i2.value, { amount: invoiceTotals(i2.value).total, date: '2026-10-10' });

  const invoices = [i1.value, p2.value];

  const result = statement('C-001', invoices, '2026-10-31');
  assert.equal(result.value.invoices.length, 2);
  assert(result.value.invoices[0].due > 0);
  assert.equal(result.value.invoices[1].due, 0);
});

test('statement returns CUSTOMER_NOT_FOUND for unknown customer', () => {
  const result = statement('C-999', [], '2026-10-31');
  assert.deepEqual(result, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('statement includes dueDate from invoice', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET30',
  });

  const r2 = issueInvoice(r1.value, []);
  const invoices = [r2.value];

  const result = statement('C-001', invoices, '2026-10-31');
  assert.equal(result.value.invoices[0].dueDate, '2026-10-31');
});

test('statement includes total from invoiceTotals', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 10, discountPercent: 0 }],
  });

  const r2 = issueInvoice(r1.value, []);
  const invoices = [r2.value];

  const result = statement('C-001', invoices, '2026-10-31');
  const invoiceTotalsValue = invoiceTotals(r2.value);
  assert.equal(result.value.invoices[0].total, invoiceTotalsValue.total);
});

// Helper function to import invoiceTotals for this test file
import { invoiceTotals } from '../src/invoices.js';

